#[cfg(feature = "system-reflection-monomethod")]
impl MonoMethod {
    #[doc = "`.ctor()` — no args"]
    pub fn new() -> Self {
        let this = <Self as ::unity::FromIlInstance>::instantiate().unwrap_or_else(|| {
            panic!(
                "{}
::{}
 failed to instantiate",
                ::core::stringify!(MonoMethod),
                ::core::stringify!(new),
            )
        });
        <Self as IMonoMethodMethods>::ctor(this);
        this
    }
}

